begin;
do $test$
declare a uuid:=gen_random_uuid();s uuid:=gen_random_uuid();p uuid:=gen_random_uuid();e uuid:=gen_random_uuid();v uuid:=gen_random_uuid();r public.service_event_intake;n integer:=0;
begin
 insert into auth.users(id) values(a),(s),(p);
 insert into public.profiles(id,display_name,role) values(a,'Intake test admin','admin'),(s,'Intake test student','aluno'),(p,'Intake test partner','profissional');
 set local role authenticated;
 perform set_config('request.jwt.claims',json_build_object('sub',a,'is_anonymous',false)::text,true);
 select * into r from public.record_service_event_intake(e,v,2,'2026-10-01',s,p,'completed','confirmed',true,true);
 if r.verification<>'unverified' or r.created_by<>a then raise exception 'unverified attribution';end if;n:=n+1;
 perform public.record_service_event_intake(e,v,2,'2026-10-01',s,p,'completed','confirmed',true,true);
 if (select count(*) from public.service_event_intake where service_id=v)<>1 then raise exception 'duplicate replay';end if;n:=n+1;
 begin perform public.record_service_event_intake(e,v,2,'2026-10-01',s,p,'cancelled','confirmed',true,true);raise exception 'changed event accepted';exception when unique_violation then n:=n+1;end;
 begin perform public.record_service_event_intake(gen_random_uuid(),v,2,'2026-10-01',s,p,'completed','confirmed',true,true);raise exception 'duplicate revision accepted';exception when unique_violation then n:=n+1;end;
 perform public.record_service_event_intake(gen_random_uuid(),v,1,'2026-10-01',s,p,'scheduled','pending',false,false);
 if (select max(revision) from public.service_event_intake where service_id=v)<>2 then raise exception 'older delivery overwrites';end if;n:=n+1;
 begin perform public.record_service_event_intake(gen_random_uuid(),v,3,'2026-11-01',s,p,'completed','confirmed',true,true);raise exception 'period changed';exception when invalid_parameter_value then n:=n+1;end;
 begin perform public.record_service_event_intake(gen_random_uuid(),v,3,'2026-10-01',p,s,'completed','confirmed',true,true);raise exception 'identity changed';exception when invalid_parameter_value then n:=n+1;end;
 begin perform public.record_service_event_intake(gen_random_uuid(),gen_random_uuid(),1,'2026-10-02',s,p,'completed','confirmed',true,true);raise exception 'nonmonth accepted';exception when invalid_parameter_value then n:=n+1;end;
 begin update public.service_event_intake set verification='verified';raise exception 'direct update';exception when insufficient_privilege then n:=n+1;end;
 begin delete from public.service_event_intake;raise exception 'direct delete';exception when insufficient_privilege then n:=n+1;end;
 begin insert into public.service_event_intake select * from public.service_event_intake;raise exception 'direct insert';exception when insufficient_privilege then n:=n+1;end;
 perform set_config('request.jwt.claims',json_build_object('sub',s,'is_anonymous',false,'user_metadata',json_build_object('role','admin'))::text,true);
 if exists(select 1 from public.service_event_intake) then raise exception 'student can read intake';end if;n:=n+1;
 begin perform public.record_service_event_intake(e,v,2,'2026-10-01',s,p,'completed','confirmed',true,true);raise exception 'student can replay';exception when insufficient_privilege then n:=n+1;end;
 perform set_config('request.jwt.claims',json_build_object('sub',a,'is_anonymous',true)::text,true);
 begin perform public.record_service_event_intake(e,v,2,'2026-10-01',s,p,'completed','confirmed',true,true);raise exception 'anonymous admin';exception when insufficient_privilege then n:=n+1;end;
 set local role anon;
 begin perform public.record_service_event_intake(e,v,2,'2026-10-01',s,p,'completed','confirmed',true,true);raise exception 'anon execute';exception when insufficient_privilege then n:=n+1;end;
 reset role;
 update public.profiles set role='aluno' where id=a;
 set local role authenticated;
 perform set_config('request.jwt.claims',json_build_object('sub',a,'is_anonymous',false)::text,true);
 begin perform public.record_service_event_intake(e,v,2,'2026-10-01',s,p,'completed','confirmed',true,true);raise exception 'demoted admin';exception when insufficient_privilege then n:=n+1;end;
 reset role;
 if exists(select 1 from public.wallet_accounts where user_id in(a,s,p)) then raise exception 'intake created wallet';end if;n:=n+1;
 if n<>17 then raise exception 'unexpected check count %',n;end if;
end $test$;
select '17 intake checks passed; fixtures rolled back' as result;
rollback;
